from __future__ import annotations
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from lib import L, MCQ, FILL, READ, EQ, U, idea
I = idea

def L2(*a, **k):
    """Teach lesson with exactly 2 retrievals so concept+2+explain = 4 exercises."""
    les = L(*a, **k)
    assert len(les["retrieval"]) == 2, les["slug"]
    return les

